+    expect(d?.sourceId).toBe(`watchdog:fleet-feed@${item.since}`);
+    // Same episode re-derived -> identical delivery (dedupe can work).
+    expect(watchdogDeliveries([item])[0]?.sourceId).toBe(d?.sourceId);
+  });
